    n, m, s, t, edges = parse_input(input_str)

    # Check if already disconnected (0 roads needed)
    adj = build_adj(edges)
    if not bfs(adj, s, t, set()):
        return "0\n0\n"

    # Try removing 1 road
    min_cost = float('inf')
    best_single_edge = None

    for i, (_, _, w, idx) in enumerate(edges):
        if w >= min_cost:
            continue
        # Temporarily remove this edge
        excluded = {idx}
        if not bfs(adj, s, t, excluded):
            if w < min_cost:
                min_cost = w
                best_single_edge = idx

    if best_single_edge is not None:
        return f"{min_cost}\n1\n{best_single_edge}"

    # Try removing 2 roads
    min_cost = float('inf')
    best_pair = None

    # Optimization: only consider edges that are on some path from s to t
    # First find all edges on paths using BFS from s and from t (reversed)
    def get_edges_on_path():
        in_s = set()
        queue = deque([s])
        in_s.add(s)
        while queue:
            u = queue.popleft()
            if u in adj:
                for v, _ in adj[u].items():
                    if v not in in_s:
                        in_s.add(v)
                        queue.append(v)

        in_t = set()
        queue = deque([t])
        in_t.add(t)
        while queue:
            u = queue.popleft()
            if u in adj:
                for v, _ in adj[u].items():
                    if v not in in_t:
                        in_t.add(v)
                        queue.append(v)

        edge_ids = set()
        for u, v, w, idx in edges:
            if u in in_s and v in in_t:
                edge_ids.add(idx)
            elif u in in_t and v in in_s:
                edge_ids.add(idx)
        return edge_ids

    relevant_edges = get_edges_on_path()

    # Try all pairs of relevant edges
    relevant_list = list(relevant_edges)
    for i in range(len(relevant_list)):
        for j in range(i + 1, len(relevant_list)):
            idx1, idx2 = relevant_list[i], relevant_list[j]
            if idx1 >= min_cost or idx2 >= min_cost:
                continue
            excluded = {idx1, idx2}
            if not bfs(adj, s, t, excluded):
                cost = edges[idx1-1][2] + edges[idx2-1][2]
                if cost < min_cost:
                    min_cost = cost
                    best_pair = (idx1, idx2)

    if best_pair:
        idx1, idx2 = best_pair
        return f"{min_cost}\n2\n{idx1} {idx2}"

    return "-1"

