from collections import defaultdict
import math

class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]
        self.level = []

    def add_edge(self, u, v, cap):
        self.graph[u].append([v, cap, len(self.graph[v])])
        self.graph[v].append([u, 0, len(self.graph[u]) - 1])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        self.level[s] = 0
        queue = [s]
        while queue:
            u = queue.pop(0)
            for v, cap, rev in self.graph[u]:
                if cap > 0 and self.level[v] < 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, t, f, iter):
        if u == t:
            return f
        for i in range(iter[u], len(self.graph[u])):
            v, cap, rev = self.graph[u][i]
            if cap > 0 and self.level[u] < self.level[v]:
                d = self.dfs(v, t, min(f, cap), iter)
                if d > 0:
                    self.graph[u][i][1] -= d
                    self.graph[v][rev][1] += d
                    return d
            iter[u] += 1
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            iter = [0] * self.n
            while True:
                f = self.dfs(s, t, float('inf'), iter)
                if f == 0:
                    break
                flow += f
        return flow

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Convert to 0-indexed
    pairs = []
    for i in range(m):
        u, v = map(int, lines[2 + i].split())
        pairs.append((u - 1, v - 1))

    def get_factors MOD = defaultdict(int)
        d = 2
        while d * d <= num:
            while num % d == 0:
                factors[d] += 1
                num //= d
            d += 1
        if num > 1:
            factors[num] += 1
        return factors

    # Assign each position to odd/even group and collect factors
    pos_to_odd = defaultdict(list)  # odd-indexed positions -> factors
    pos_to_even = defaultdict(list)  # even-indexed positions -> factors

    for idx in range(n):
        factors = get_factors(a[idx])
        if idx % 2 == 0:
            # 0-indexed even = 1-indexed odd
            pos_to_odd[idx].extend(factors.items())
        else:
            # 0-indexed odd = 1-indexed even  
            pos_to_even[idx].extend(factors.items())

    all_primes = set()
