def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "NO"

    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    if n == 1:
        return "YES\n0 "

    res = []
    res.append(1)

    last0 = None  # last element in increasing sequence
    last1 = None  # last element in decreasing sequence

    # Process each element
    for i in range(n):
        x = a[i]

        if i == 0:
            res.append(0)
            last0 = x
            continue

        if x == last0:
            # Equal to last in increasing, must switch to decreasing
            res.append(1)
            last1 = x
        else:
            # Try to assign optimally
            res.append(1)
            last1 = x

    return "YES\n" + " ".join(map(str, res))
