    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "-1\n"

    n, h, w = map(int, lines[0].split())
    pattern = lines[1]

    # Calculate the displacement over one cycle
    cx, cy = 0, 0  # cumulative x (column), y (row) changes
    for ch in pattern:
        if ch == 'R':
            cx += 1
        elif ch == 'L':
            cx -= 1
        elif ch == 'U':
            cy -= 1
        elif ch == 'D':
            cy += 1

    # Check for infinite loop conditions
    # If both x and y displacement is 0 (no net movement), we could loop
    if cx == 0 and cy == 0:
        # The robot returns to same position after each cycle
        # Check if it hits a wall within one cycle from any start
        # If it doesn't hit wall, it can loop forever
        temp_r, temp_c = 0, 0
        current_x, current_y = 0, 0
        hit_wall = False
        for ch in pattern:
            if ch == 'R':
                temp_c += 1
            elif ch == 'L':
                temp_c -= 1
            elif ch == 'U':
                temp_r -= 1
            elif ch == 'D':
                temp_r += 1
            if temp_c < 0 or temp_c >= w or temp_r < 0 or temp_r >= h:
                hit_wall = True
                break
        # If no wall hit in a cycle and net displacement is 0, it's an infinite loop
        if not hit_wall:
            # But we need to check from various starting positions
            # Actually, we simulate one cycle from start position (0,0)
            # to see if it ever would leave grid
            current_x = 0
            current_y = 0
            for ch in pattern:
                if ch == 'R':
                    current_x += 1
                elif ch == 'L':
                    current_x -= 1
                elif ch == 'U':
                    current_y -= 1
                elif ch == 'D':
                    current_y += 1
                if current_x < 0 or current_x >= w or current_y < 0 or current_y >= h:
                    hit_wall = True
                    break
            if not hit_wall:
                return "-1\n"

    # Calculate prefix sums for position changes
    px = [0] * (n + 1)
    py = [0] * (n + 1)
    tx = [0] * (n + 1)
    ty = [0] * (n + 1)

    for i in range(n):
        px[i + 1] = px[i]
        py[i + 1] = py[i]
        tx[i + 1] = tx[i]
        ty[i + 1] = ty[i]
        ch = pattern[i]
        if ch == 'R':
            px[i + 1] += 1
        elif ch == 'L':
            px[i + 1] -= 1
        elif ch == 'U':
            py[i + 1] -= 1
        elif ch == 'D':
            py[i + 1] += 1
