    for i in range(1, m + 1):
        if i < len(lines):
            parts = list(map(int, lines[i].split()))
            u, v, w = parts[0] - 1, parts[1] - 1, parts[2]
            edges.append((u, v, w))

    # DSU implementation
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry
            return True
        return False

    # Sort edges by weight
    edges_sorted = sorted(edges, key=lambda x: x[2])

    mst_weight = 0
    xor_sum_pre = 0
    edges_count = 0

    # Kruskal's on pre-assigned edges first
    for u, v, w in edges_sorted:
        if union(u, v):
            mst_weight += w
            xor_sum_pre ^= w
            edges_count += 1

    # Connect remaining components with unassigned edges (weight 0)
    for u in range(n):
        for v in range(u + 1, n):
            if union(u, v):
                edges_count += 1
                if edges_count == n - 1:
                    break
        if edges_count == n - 1:
            break

    return f"\n{mst_weight}\n"
