    lines = input_str.strip().split('\n')
    N = int(lines[0])

    ships = []
    for i in range(N):
        x, y = map(int, lines[1 + i].split())
        ships.append((x, y))

    bases = []
    for i in range(N):
        x, y = map(int, lines[N + 1 + i].split())
        bases.append((x, y))

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def on_seg(p, a, b):
        return min(a[0], b[0]) <= p[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= p[1] <= max(a[1], b[1])

    def intersect(a, b, c, d):
        c1, c2 = cross(a, b, c), cross(a, b, d)
        c3, c4 = cross(c, d, a), cross(c, d, b)
        if ((c1 > 0) != (c2 > 0)) and ((c3 > 0) != (c4 > 0)):
            return True
        if c1 == 0 and on_seg(c, a, b): return True
        if c2 == 0 and on_seg(d, a, b): return True
        if c3 == 0 and on_seg(a, c, d): return True
        if c4 == 0 and on_seg(b, c, d): return True
        return False

    for attempt in range(10000):
        perm = list(range(N))
        random.shuffle(perm)
        match = [None] * N
        uses = set()
        possible = True

        for si in perm:
            chosen = None
            for bi in range(N):
                if bi in uses:
                    continue
                valid = True
                for ai in perm[:perm.index(si)]:
                    if match[ai] is None:
                        continue
                    if intersect(ships[si], bases[bi], ships[ai], bases[match[ai]]):
                        valid = False
                        break
                if valid:
                    chosen = bi
                    break
            if chosen is None:
                possible = False
                break
            uses.add(chosen)
            match[si] = chosen + 1

        if possible:
            return '\n'.join(str(m) for m in match)

    # Use theorem: Any perfect matching has at most 1 crossing.
    # Pick hull edges greedily.
    all_p = []
    for i, p in enumerate(ships): all_p.append(p + (0, i))
    for i, p in enumerate(bases): all_p.append(p + (1, N + i))
    all_p.sort()

    hull = [all_p[0]]
    for p in all_p[1:-1]:
        while len(hull) >= 2 and cross(hull[-2][0], hull[-1][0], p[0]) <= 0:
            hull.pop()
        hull.append(p)
    hull.append(all_p[-1])

    result = [0] * N
    for i in range(len(hull) - 1):
        p1, p2 = hull[i], hull[i + 1]
        if p1[2] < N and p2[2] > N:
            result[p1[3]] = p2[2] - N + 1
        elif p1[2] > N and p2[2] < N:
            result[p2[3]] = p1[2] - N + 1

    return '\n'.join(str(r) for r in result)
