def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    p = list(map(int, lines[2].split()))
    m = int(lines[3])
    b = list(map(int, lines[4].split()))

    occ = [[] for _ in range(n + 1)]
    for i in range(n):
        occ[a[i]].append(i)

    for val in b:
        if not occ[val]:
            return "NO"

    # dp[j] = minimum cost to match b[0..j]
    # We need to track position, so dp[j] = dict mapping pos -> cost

    INF = float('inf')
    dp = {}

    for pos in occ[b[0]]:
        cost = p[pos]
        for k in range(pos):
            if a[k] < b[0]:
                cost += p[k]
        dp[pos] = cost

    if not dp:
        return "NO"

    for j in range(1, m):
        new_dp = {}
        target = b[j]
        prev_occ = occ[b[j-1]]

        for curr_pos in occ[target]:
            best = INF
            for prev_pos in prev_occ:
                if prev_pos < curr_pos:
                    # Calculate transition cost
                    trans = 0
                    for k in range(prev_pos + 1, curr_pos):
                        if a[k] >= target:
                            trans += p[k]

                    prev_best = min(dp.values())
                    cand = prev_best + trans
                    if cand < best:
                        best = cand

            new_dp[curr_pos] = best

        if not new_dp:
            return "NO"
        dp = new_dp

    final = min(dp.values())

    # Add post-cost: elements after last b
    pos = max(dp.keys())
    for k in range(pos + 1, n):
        if a[k] >= b[-1]:
            final += p[k]

