MOD = 1000000007

def solve_test_case(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    vertices = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        vertices.append((x, y))

    if n < 3:
        return "0"

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def check_edge_intersection(p1, q1, p2, q2):
        """Check if edges p1-q1 and p2-q2 intersect (properly, not sharing endpoints)"""
        d1 = cross_product(p2, q2, p1)
        d2 = cross_product(p2, q2, q1)
        d3 = cross_product(p1, q1, p2)
        d4 = cross_product(p1, q1, q2)

        if ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
           ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0)):
            return True
        return False

    def is_valid_diagonal(i, k, polygon, n):
        """Check if diagonal from i to k is valid (inside polygon, doesn't intersect edges)"""
        for q in range(n):
            r = (q + 1) % n  # Next vertex forming edge
            # Skip edges sharing endpoints with diagonal
            if q == i or r == i or q == k or r == k:
                continue
            if check_edge_intersection(polygon[i], polygon[k], polygon[q], polygon[r]):
                return False
        return True

