#!/usr/bin/env python3
"""
Solution for polygon triangulation counting problem.
Uses dynamic programming to count valid triangulations.
A diagonal is valid if it doesn't intersect any polygon edges.
"""

MOD = 1000000007

def cross_product(o, a, b):
    """Compute cross product of vectors oa and ob"""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def segments_intersect(a, b, c, d):
    """
    Check if segments ab and cd properly intersect (strict crossing).
    Returns True if segments cross each other properly.
    """
    cp1 = cross_product(c, d, a)
    cp2 = cross_product(c, d, b)
    cp3 = cross_product(a, b, c)
    cp4 = cross_product(a, b, d)

    return ((cp1 > 0 and cp2 < 0) or (cp1 < 0 and cp2 > 0)) and \
           ((cp3 > 0 and cp4 < 0) or (cp3 < 0 and cp4 > 0))

def count_triangulations(vertices):
    """Count the number of valid triangulations of polygon"""
    n = len(vertices)

    if n < 3:
        return 0

    # dp[i][j] represents valid triangulations of chain from vertex i to j
    # where j = (i + length) % n for some length
    # We use linear indexing for lengths

    dp = [[0] * n for _ in range(n)]

    # Base case: consecutive vertices have 1 "way" (no triangulation needed)
    for i in range(n):
        dp[i][(i + 1) % n] = 1

    # Fill DP for increasing chain lengths (from 2 to n-1)
    for length in range(2, n):
        for i in range(n):
            j = (i + length) % n

            if j < i:
                continue

            # Count triangulations by trying all middle vertices k
            count = 0
            for k in range(i + 1, j):
                # Check diagonal (i, k) - must not intersect polygon edges
                diagonal_ik_valid = True
                for v in range(n):
                    v_next = (v + 1) % n
                    if v == i or v_next == i or v == k or v_next == k:
                        continue
                    if segments_intersect(vertices[i], vertices[k], vertices[v], vertices[v_next]):
                        diagonal_ik_valid = False
                        break

                if not diagonal_ik_valid:
                    continue

                # Check diagonal (k, j) - must not intersect polygon edges  
                diagonal_kj_valid = True
                for v in range(n):
                    v_next = (v + 1) % n
                    if v == k or v_next == k or v == j or v_next == j:
                        continue
                    if segments_intersect(vertices[k], vertices[j], vertices[v], vertices[v_next]):
                        diagonal_kj_valid = False
                        break

                if not diagonal_kj_valid:
                    continue

                # Add product of triangulations
                count = (count + dp[i][k] * dp[k][j]) % MOD

            dp[i][j] = count

    return dp[0][n - 1]

def solution(input_str):
    """
    Parse input string and return the number of triangulations.
    Input format: First line is n, then n lines of coordinates.
    """
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    vertices = []
    for i in range(1, n + 1):
        coords = list(map(int, lines[i].split()))
        vertices.append(tuple(coords))

    result = count_triangulations(vertices)
    return str(result)
