def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0"
    n, m = map(int, lines[0].split())

    # Parse grid
    grid = []
    for i in range(1, n + 1):
        grid.append(list(lines[i]))

    MOD = 1000003

    def has_end(ptype, direction):
        """Check if pipe type has end in given direction
        directions: 0=top, 1=right, 2=bottom, 3=left"""
        if ptype == 1:  # top, left
            return direction in [0, 3]
        if ptype == 2:  # top, right
            return direction in [0, 1]
        if ptype == 3:  # bottom, left
            return direction in [2, 3]
        if ptype == 4:  # bottom, right
            return direction in [2, 1]
        return False

    def check_compatibility(i, j):
        """Verify if cell (i,j) with filled pipe satisfies constraints with neighbors"""
        pt = int(grid[i][j])

        # Check up neighbor
        if i > 0 and grid[i-1][j] != '.':
            top_pt = int(grid[i-1][j])
            # cell(i,j)'s top must match cell(i-1,j)'s bottom
            pt_top = has_end(pt, 0)  # (i,j)'s top
            top_bot = has_end(top_pt, 2)  # (i-1,j)'s bottom
            if pt_top != top_bot:
                return False

        # Check down neighbor
        if i < n - 1 and grid[i+1][j] != '.':
            bot_pt = int(grid[i+1][j])
            # cell(i,j)'s bottom must match cell(i+1,j)'s top
            pt_bot = has_end(pt, 2)  # (i,j)'s bottom
            bot_top = has_end(bot_pt, 0)  # (i+1,j)'s top
            if pt_bot != bot_top:
                return False

        # Check left neighbor
        if j > 0 and grid[i][j-1] != '.':
            left_pt = int(grid[i][j-1])
            # cell(i,j)'s left must match cell(i,j-1)'s right
            pt_left = has_end(pt, 3)  # (i,j)'s left
            left_right = has_end(left_pt, 1)  # (i,j-1)'s right
            if pt_left != left_right:
                return False

        # Check right neighbor
        if j < m - 1 and grid[i][j+1] != '.':
            right_pt = int(grid[i][j+1])
            # cell(i,j)'s right must match cell(i,j+1)'s left
            pt_right = has_end(pt, 1)  # (i,j)'s right
            right_left = has_end(right_pt, 3)  # (i,j+1)'s left
            if pt_right != right_left:
                return False

        return True

    # Step 1: Check all pre-filled cells for conflicts with their neighbors
    for i in range(n):
        for j in range(m):
            if grid[i][j] != '.':
                if not check_compatibility(i, j):
                    return "0"

    # Step 2: Count empty cells - each can typically have 2 valid pipe types
    empty_count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                empty_count += 1

    # Each '.' cell has constraints from left and top neighbors
    # In general, the answer is 2^empty_count (each '.' contributes factor of 2)
    # But if there are global constraints, it could be different

    if empty_count == 0:
        return "1"

    ans = pow(2, empty_count, MOD)
    return str(ans)
