Looking at this problem, I need to solve a constraint satisfaction problem where elements must be grouped based on symmetry constraints.

Let me analyze the problem:
- If `x` is in set A, then `a-x` must also be in set A (if `a-x` exists in input)
- If `x` is in set B, then `b-x` must also be in set B (if `b-x` exists in input)

This creates constraints where certain elements must be in the same set. I can model this using a graph/union-find approach.

```python
def solution(input_str):
    parts = input_str.strip().split()
    n = int(parts[0])
    a = int(parts[1])
    b = int(parts[2])
    p = list(map(int, parts[3:]))

    pos = {val: i for i, val in enumerate(p)}

    # Union-Find to group positions that must be in the same set
    parent = list(range(n))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Build components: union positions of x and its complements
    for i in range(n):
        x = p[i]
        # If a-x exists, these positions must be in same set (A)
        if (a - x) in pos:
            union(i, pos[a - x])
        # If b-x exists, these positions must be in same set (B)
        if (b - x) in pos:
            union(i, pos[b - x])

    # Initialize answer array
    ans = [0] * n
    possible = True

    # For each component, try to find a valid assignment
    for comp_root in range(n):
        if comp_root != find(comp_root):
            continue

        # Collect all elements in this component
        comp_indices = [i for i in range(n) if find(i) == comp_root]

        # Build a component-level variable for our assignment
        comp_valid = True

        # Try assigning this component to set 0
        # Check if all elements in component can belong to set 0
        can_be_0 = True
        for idx in comp_indices:
            x = p[idx]
            # Check complement for set 0 (a-x)
            if (a - x) in pos:
                complement_pos = pos[a - x]
                if find(complement_pos) != comp_root:
                    # Complement is outside this component, can't be together
                    can_be_0 = False
                    break

        if not can_be_0:
            # Try setting it to 1
            can_be_1 = True
            for idx in comp_indices:
                x = p[idx]
                # Check complement for set 1 (b-x)  
                if (b - x) in pos:
                    complement_pos = pos[b - x]
                    if find(complement_pos) != comp_root:
                        can_be_1 = False
                        break

            if not can_be_1:
                possible = False
                break

        # Assign the component
        if can_be_0:
            for idx in comp_indices:
                ans[idx] = 0
        else:
            for idx in comp_indices:
                ans[idx] = 1

    if possible:
        return "YES\n" + " ".join(map(str, ans)) + "\n"
    else:
        return "NO\n"
